def predict(parameters, state, history):
    import numpy as np

    alpha = float(parameters["alpha"])

    if len(history["response"]) == 0:
        return np.array([0.5, 0.5])

    prev_response = history["response"][-1]

    p = np.zeros(2)
    p[prev_response] = alpha
    p[1 - prev_response] = 1.0 - alpha

    return p

